-- Three recent licensed full films; original English audio is explicitly labelled.
begin;
alter table public.movies drop constraint "movies_posterUrl_check";
alter table public.movies add constraint "movies_posterUrl_check" check("posterUrl"='' or "posterUrl" ~ '^https://' or "posterUrl" ~ '^/assets/posters/[a-z0-9-]+\.(svg|jpg|png)$');
select 'The Manifestation','Потеряв семейные сбережения, трейдер ищет выход в необычной практике самопомощи. Его внутренний голос обретает облик женщины, чьи советы постепенно становятся опасными.',2024,85,(select "directorID" from public.directors where "fullName"='Geert Heetebrij' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Thriller' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Inbar Lavi' order by "actorID" limit 1),0,'/assets/posters/the-manifestation-2024.jpg','https://www.youtube.com/watch?v=pPpqd-A4TRA','https://www.youtube.com/embed/pPpqd-A4TRA','https://visionfilms.net/film-detail?id=a9b484ca-bbb0-ee11-829d-0e4a64f8a357','Movie Central · Licensed from Vision Films. All rights reserved. Полная версия на английском; русская озвучка не заявлена.',true,array['thoughtful'],array['Полный фильм','На английском','Movie Central'],4,true,'Английский' where not exists(select 1 from public.movies where title='The Manifestation' and "releaseYear"=2024);
select 'Sirona','Девушка со сверхъестественными способностями сбегает из секретной лаборатории. Нанятые для её поимки наёмники оказываются перед выбором между приказом и совестью.',2023,104,(select "directorID" from public.directors where "fullName"='Wesley Clark' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Sci-Fi' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Ashlynn Hideman' order by "actorID" limit 1),0,'/assets/posters/sirona-2023.png','https://www.youtube.com/watch?v=XF33FZh5CeU','https://www.youtube.com/embed/XF33FZh5CeU','https://crankedupfilms.com/sirona','Movie Central · Licensed from Good Deed Entertainment / Cranked Up Films. All rights reserved. Полная версия на английском; русская озвучка не заявлена.',true,array['adrenaline','thoughtful'],array['Полный фильм','На английском','Movie Central'],4,true,'Английский' where not exists(select 1 from public.movies where title='Sirona' and "releaseYear"=2023);
select 'The Hive','Вернувшись домой, супруги обнаруживают незнакомцев. Попытка получить помощь оборачивается борьбой за жизнь, а происхождение захватчиков оказывается неожиданным.',2023,87,(select "directorID" from public.directors where "fullName"='Jared Allmond' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Thriller' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Timothy Haug' order by "actorID" limit 1),0,'/assets/posters/the-hive-2023.jpg','https://www.youtube.com/watch?v=FUbbbwIUI6Q','https://www.youtube.com/embed/FUbbbwIUI6Q','https://www.youtube.com/watch?v=FUbbbwIUI6Q','Movie Central · Licensed from Buffalo 8. All rights reserved. Полная версия на английском; русская озвучка не заявлена.',true,array['horror','adrenaline'],array['Полный фильм','На английском','Movie Central'],5,true,'Английский' where not exists(select 1 from public.movies where title='The Hive' and "releaseYear"=2023);
commit;
