insert into public.movies(title,description,"releaseYear","durationMinutes","directorID","genreID","mainActorID",rating,"posterUrl","watchUrl","watchSourceUrl","licenseUrl",attribution,"isFree",moods,"vibeTags",intensity,published,"languageName")
insert into public.movieactors("movieID","actorID") select m."movieID",a."actorID" from public.movies m join public.actors a on a."fullName"='Inbar Lavi' where m.title='The Manifestation' and m."releaseYear"=2024 on conflict("movieID","actorID") do nothing;
